import{_ as t,o as r,c as a,a2 as i}from"./chunks/framework.BHcoJYMQ.js";const p=JSON.parse('{"title":"Research brief","description":"","frontmatter":{},"headers":[],"relativePath":"research/brief.md","filePath":"research/brief.md","lastUpdated":1794242772000}'),o={name:"research/brief.md"};function n(s,e,d,c,l,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="research-brief" tabindex="-1">Research brief <a class="header-anchor" href="#research-brief" aria-label="Permalink to &quot;Research brief&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Understand how focused clothing brands compete, using plain white T-shirts as our product lens. Build a credible competitor landscape that can inform a future brand. The current phase is information collection.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><ul><li><strong>Product:</strong> plain white T-shirts. Record neckline, fit, intended wearer, and whether the item is an undershirt or outerwear.</li><li><strong>Primary lens:</strong> brands built around one product or a narrow hero-product proposition.</li><li><strong>Comparison unit:</strong> one named white T-shirt SKU, variant, and pack size at a time.</li><li><strong>Market and audience:</strong> undecided. Always record sales region, currency, and intended customer rather than assuming comparability.</li><li><strong>Later work:</strong> brand identity, sourcing, product design, unit economics, and launch planning follow research.</li></ul><h2 id="competitor-groups" tabindex="-1">Competitor groups <a class="header-anchor" href="#competitor-groups" aria-label="Permalink to &quot;Competitor groups&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Working definition</th><th>Role</th></tr></thead><tbody><tr><td>Single-product brand</td><td>Current assortment is centered on one product type; variations do not automatically imply a broad range</td><td>Closest business-model reference</td></tr><tr><td>T-shirt specialist</td><td>T-shirts are central but the assortment may include other products</td><td>Direct product and positioning comparison</td></tr><tr><td>Broader benchmark</td><td>A wider apparel brand with a relevant white T-shirt</td><td>Price, quality claims, distribution, or customer expectation benchmark</td></tr></tbody></table><p>Check the current catalog before assigning a group. A brand that launched with one product may have expanded. Record origin story separately from current assortment.</p><h2 id="questions-to-answer" tabindex="-1">Questions to answer <a class="header-anchor" href="#questions-to-answer" aria-label="Permalink to &quot;Questions to answer&quot;">​</a></h2><ol><li>What promise makes a seemingly basic product feel distinctive?</li><li>Which customers and wearing occasions does each brand serve?</li><li>How do fabric, opacity, fit, neck construction, and durability claims differ?</li><li>What are the comparable single-shirt and per-shirt pack prices?</li><li>How do shipping, returns, channels, and availability affect the offer?</li><li>What do customers repeatedly value or criticize, and how strong is that evidence?</li><li>Which potential gaps deserve customer interviews or physical product testing?</li></ol><h2 id="initial-research-target" tabindex="-1">Initial research target <a class="header-anchor" href="#initial-research-target" aria-label="Permalink to &quot;Initial research target&quot;">​</a></h2><p>Working target: 8–12 qualified profiles across the three groups. This is a planning target, not a finding. Validate the market and audience before narrowing the final sample.</p>',12)])])}const m=t(o,[["render",n]]);export{p as __pageData,m as default};
